using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // EF Core 9 breaking change: discriminator property renamed to "$type".
            // Preserve "Discriminator" for compatibility with existing 500K documents
            // and direct SQL queries that reference c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Product");

            // EF Core 9 breaking change: id format changed from "EntityName|Key" to just "Key".
            // Preserve "Product|{Id}" format for compatibility with existing documents.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id");
            entity.UseIdProperty(p => p.Id, idValue => $"Product|{idValue}");
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        base.OnConfiguring(optionsBuilder);
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

