using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;
using System.Linq;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // EF Core 9 breaking change #1: discriminator property renamed from
            // "Discriminator" to "$type". Preserve old name for existing documents
            // and direct SQL queries that reference c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Product");

            // EF Core 9 breaking change #2: id values no longer include the
            // discriminator prefix. EF8 generated "Product|123", EF9 generates "123".
            // Preserve the old format via a shadow property mapped to JSON "id".
            entity.Property<string>("__id")
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        base.OnConfiguring(optionsBuilder);
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } = default!; }

/// <summary>
/// Generates id values in the EF Core 8 format: "Product|{key}" for backward
/// compatibility with existing Cosmos DB documents.
/// </summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    protected override string GenerateValue(EntityEntry entry)
    {
        var key = entry.Property("Id").CurrentValue;
        return $"Product|{key}";
    }
}

